import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    # Physics constants estimated from recorded data
    C_POS = 1 / 35.0       # position scaling: delta_pos ≈ avg_velocity * dt / 35
    FRICTION = 0.975       # multiplicative velocity decay per frame
    COLL_DIST = 0.38       # collision threshold distance
    BOUNDS = 5.5           # approximate scene boundary for exit detection

    if horizon is None:
        horizon = 127.0
    if start is None:
        start = 0.0

    # Retrieve motion log for state initialization
    motion_node = None
    for node in scope_nodes(doc, scope):
        if node["kind"] == "table" and "Motion log" in node["title"]:
            motion_node = node
            break

    motion_data = {}
    if motion_node:
        for _, row in table_rows(motion_node):
            f = float(row["frame"])
            obj_id = row["object"].split()[0]
            if obj_id not in motion_data:
                motion_data[obj_id] = {}
            motion_data[obj_id][f] = {
                "x": float(row["x"]), "y": float(row["y"]),
                "vx": float(row["vx"]), "vy": float(row["vy"])
            }

    def get_state_at(obj_id, t):
        """Get latest recorded state at or before time t."""
        if obj_id not in motion_data:
            return {"x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0}
        frames = sorted(motion_data[obj_id].keys())
        best = frames[0]
        for f in frames:
            if f <= t:
                best = f
            else:
                break
        return motion_data[obj_id][best]

    # Initialize state from inputs
    state = {}
    for inp in inputs:
        obj_id = inp["entities"][0]
        t_enter = inp["time"]
        if t_enter <= start:
            rec = get_state_at(obj_id, start)
            state[obj_id] = {
                "x": rec["x"], "y": rec["y"], "vx": rec["vx"], "vy": rec["vy"],
                "active": True, "exited": False
            }
        else:
            state[obj_id] = {
                "x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0,
                "active": False, "enter_time": t_enter, "exited": False
            }

    outcomes = []
    t = start
    dt = 1.0

    while t < horizon:
        # Activate objects entering at this frame
        for obj_id, s in state.items():
            if not s["active"] and s["enter_time"] <= t:
                s["active"] = True
                rec = get_state_at(obj_id, s["enter_time"])
                s.update({"x": rec["x"], "y": rec["y"], "vx": rec["vx"], "vy": rec["vy"]})

        # Update positions and apply friction
        for obj_id, s in state.items():
            if s["active"] and not s["exited"]:
                s["x"] += s["vx"] * C_POS * dt
                s["y"] += s["vy"] * C_POS * dt
                s["vx"] *= FRICTION
                s["vy"] *= FRICTION

                # Check for exit
                if abs(s["x"]) > BOUNDS or abs(s["y"]) > BOUNDS:
                    s["exited"] = True
                    outcomes.append({
                        "time": round(t, 1),
                        "kind": "exit",
                        "entities": [obj_id],
                        "value": None,
                        "src": []
                    })

        # Check collisions
        active_objs = [oid for oid, s in state.items() if s["active"] and not s["exited"]]
        for i in range(len(active_objs)):
            for j in range(i + 1, len(active_objs)):
                o1, o2 = active_objs[i], active_objs[j]
                s1, s2 = state[o1], state[o2]
                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist = math.hypot(dx, dy)

                if dist < COLL_DIST and dist > 1e-6:
                    outcomes.append({
                        "time": round(t, 1),
                        "kind": "collision",
                        "entities": [o1, o2],
                        "value": None,
                        "src": []
                    })
                    # Elastic collision response along the collision normal
                    nx = dx / dist
                    ny = dy / dist
                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    dvn = dvx * nx + dvy * ny

                    if dvn > 0:  # Objects moving towards each other
                        s1["vx"] -= dvn * nx
                        s1["vy"] -= dvn * ny
                        s2["vx"] += dvn * nx
                        s2["vy"] += dvn * ny

                        # Separate objects to prevent sticking
                        overlap = COLL_DIST - dist
                        s1["x"] -= overlap * nx
                        s1["y"] -= overlap * ny
                        s2["x"] += overlap * nx
                        s2["y"] += overlap * ny

        t += dt

    # Deduplicate outcomes that occur within the same frame or very close in time
    final_outcomes = []
    for out in sorted(outcomes, key=lambda x: (x["time"], tuple(sorted(x["entities"])))):
        if not final_outcomes:
            final_outcomes.append(out)
        else:
            last = final_outcomes[-1]
            if (abs(out["time"] - last["time"]) < 0.5 and 
                out["kind"] == last["kind"] and 
                sorted(out["entities"]) == sorted(last["entities"])):
                continue
            final_outcomes.append(out)

    return final_outcomes

