            m = re.match(r'Object (\d+): (\w+) (\w+) (\w+)', line)
            if m:
                materials[m.group(1)] = m.group(2)  # color
                # Actually let's parse the full description
                m2 = re.match(r'Object (\d+): (.+)', line)
                if m2:
                    desc = m2.group(2)
                    # e.g., "gray rubber cylinder (color=gray, material=rubber, shape=cylinder)"
