            obj = r[1]
            obj_id = obj.split()[0]
            x, y = float(r[2]), float(r[3])
            vx, vy = float(r[4]), float(r[5])
            speed = float(r[6])

            if obj_id not in obj_data:
                obj_data[obj_id] = {}
            obj_data[obj_id][frame] = {"x": x, "y": y, "vx": vx, "vy": vy, "speed": speed}

        # Get collision events
        event_node = video_events[video_title]
        for line in event_node["lines"]:
            import re
            m = re.match(r'Frame (\d+): Object (\d+).*collides with Object (\d+)', line)
            if m:
                frame = int(m.group(1))
                o1, o2 = m.group(2), m.group(3)
                print(f"\nCollision at frame {frame}: {o1} ({materials.get(o1,'?')}) x {o2} ({materials.get(o2,'?')})")

                # Show velocities before and after
                for obj_id in [o1, o2]:
                    if obj_id in obj_data:
                        frames = sorted(obj_data[obj_id].keys())
                        # Find frame before collision
                        before_frames = [f for f in frames if f < frame]
                        after_frames = [f for f in frames if f >= frame]

                        if before_frames:
                            bf = before_frames[-1]
                            print(f"  {obj_id} before (frame {bf}): v=({obj_data[obj_id][bf]['vx']:.2f},{obj_data[obj_id][bf]['vy']:.2f}), speed={obj_data[obj_id][bf]['speed']:.2f}")
